    Lock m_lock; Sink* m_pNotify;
    int SetNotify(Sink* pNotify)
    {
        AutoLock lck(&m_lock);
        if (pNotify) pNotify->AddRef();
        if (m_pNotify) m_pNotify->Release();
        m_pNotify = pNotify;
        return 0;
    }
};
